-- =====================================================================
-- China Talent Bridge — Consolidated Database Schema
-- =====================================================================
-- Authored by: @qa  (DB & Quality)
--
-- This is a READ-ONLY consolidated view of the schema for reference. The
-- RUNNABLE source of truth is the ordered migration set:
--     apps/api/src/db/migrations/001..015
-- Apply with:  npm --workspace @chinatalent/api run migrate
--
-- 28 tables, RLS enabled + FORCED on every table. Do not edit this file to
-- change the schema — add a new migration instead, then regenerate this file.
-- This file is generated by concatenating the migrations in numeric order.
-- =====================================================================


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/001_extensions_and_helpers.sql
-- =====================================================================
-- 001_extensions_and_helpers.sql
-- Foundation: extensions, roles, RLS identity helpers, and shared triggers.
-- Idempotent: safe to run repeatedly.
--
-- WHY this file runs first: every later migration relies on gen_random_uuid()
-- (pgcrypto), the set_updated_at() trigger, and the app_current_user_id()
-- identity helper used by all RLS policies in 015.

-- ---------------------------------------------------------------------------
-- Extensions
-- ---------------------------------------------------------------------------
-- pgcrypto -> gen_random_uuid() for primary keys.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
-- pg_trgm -> trigram GIN indexes for fuzzy search on titles / names.
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ---------------------------------------------------------------------------
-- Roles
-- ---------------------------------------------------------------------------
-- Supabase already provisions anon / authenticated / service_role. We create
-- them defensively so these migrations also run on a vanilla Postgres (e.g. a
-- local CI database for the RLS test suite). They are NOLOGIN groups.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    CREATE ROLE anon NOLOGIN NOINHERIT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    CREATE ROLE authenticated NOLOGIN NOINHERIT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    CREATE ROLE service_role NOLOGIN NOINHERIT BYPASSRLS;
  END IF;
END
$$;

-- ---------------------------------------------------------------------------
-- Identity helper used by ALL RLS policies
-- ---------------------------------------------------------------------------
-- Returns the current request's user id (a profiles.id / auth.users.id).
--
-- It reads, in order of preference:
--   1. The Supabase JWT claim `sub` (set automatically by Supabase on every
--      authenticated PostgREST/Realtime request).
--   2. A plain `app.current_user_id` GUC, which the RLS test suite sets via
--      `SET LOCAL app.current_user_id = '<uuid>'` so tests can impersonate a
--      user without minting a real JWT.
--
-- `STABLE` (not VOLATILE) so the planner can cache it within a statement.
-- The `true` second arg to current_setting suppresses errors when unset.
CREATE OR REPLACE FUNCTION app_current_user_id()
RETURNS uuid
LANGUAGE sql
STABLE
AS $$
  SELECT COALESCE(
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub',
    NULLIF(current_setting('app.current_user_id', true), '')
  )::uuid;
$$;

-- True when there is an authenticated principal on the request.
CREATE OR REPLACE FUNCTION app_is_authenticated()
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT app_current_user_id() IS NOT NULL;
$$;

-- ---------------------------------------------------------------------------
-- Shared trigger: keep updated_at fresh on every UPDATE
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/002_profiles.sql
-- =====================================================================
-- 002_profiles.sql
-- The central identity table. One row per platform user, keyed by the same
-- UUID Supabase Auth assigns in auth.users. Everything else hangs off profiles.

CREATE TABLE IF NOT EXISTS profiles (
  id                  uuid PRIMARY KEY,
  -- Account archetype. A single account is exactly one of these.
  role                text NOT NULL DEFAULT 'worker'
                        CHECK (role IN ('worker', 'employer', 'admin')),
  display_name        text,
  full_name           text,
  avatar_url          text,
  country             text,                         -- ISO 3166-1 alpha-2
  timezone            text,                         -- IANA tz, e.g. 'Asia/Shanghai'
  locale              text NOT NULL DEFAULT 'en',
  preferred_language  text NOT NULL DEFAULT 'en',   -- drives message translation
  phone               text,
  bio                 text,
  is_active           boolean NOT NULL DEFAULT true,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);

-- Link to Supabase Auth. Added separately + guarded so these migrations still
-- run on a vanilla Postgres that has no `auth` schema (e.g. local CI).
-- ON DELETE CASCADE: deleting the auth user tears down their profile graph.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables
             WHERE table_schema = 'auth' AND table_name = 'users')
     AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'profiles_id_fkey')
  THEN
    ALTER TABLE profiles
      ADD CONSTRAINT profiles_id_fkey
      FOREIGN KEY (id) REFERENCES auth.users (id) ON DELETE CASCADE;
  END IF;
END
$$;

-- Indexes
CREATE INDEX IF NOT EXISTS idx_profiles_role ON profiles (role);
-- Trigram index for typeahead search on names.
CREATE INDEX IF NOT EXISTS idx_profiles_display_name_trgm
  ON profiles USING gin (display_name gin_trgm_ops);

-- Triggers
CREATE OR REPLACE TRIGGER trg_profiles_updated_at
  BEFORE UPDATE ON profiles
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/003_lookup_tables.sql
-- =====================================================================
-- 003_lookup_tables.sql
-- Reference data: categories (top-level domains) and skills (tags within them).
-- These are world-readable and only writable by admins (see RLS in 015).

CREATE TABLE IF NOT EXISTS categories (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug        text NOT NULL UNIQUE,           -- stable machine key, e.g. 'software-engineering'
  name        text NOT NULL,
  description text,
  sort_order  int  NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS skills (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id uuid REFERENCES categories (id) ON DELETE SET NULL,
  slug        text NOT NULL UNIQUE,           -- e.g. 'typescript'
  name        text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_skills_category_id ON skills (category_id);
-- Trigram index for skill typeahead.
CREATE INDEX IF NOT EXISTS idx_skills_name_trgm
  ON skills USING gin (name gin_trgm_ops);


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/004_worker_profiles.sql
-- =====================================================================
-- 004_worker_profiles.sql
-- The worker-facing extension of a profile, plus the worker<->skill join.
-- One worker_profile per profile (enforced by UNIQUE on profile_id).

CREATE TABLE IF NOT EXISTS worker_profiles (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id          uuid NOT NULL UNIQUE
                        REFERENCES profiles (id) ON DELETE CASCADE,
  headline            text,
  summary             text,
  years_experience    int  CHECK (years_experience IS NULL OR years_experience >= 0),
  hourly_rate_usd     numeric(10, 2) CHECK (hourly_rate_usd IS NULL OR hourly_rate_usd >= 0),
  availability        text NOT NULL DEFAULT 'not_available'
                        CHECK (availability IN
                          ('full_time', 'part_time', 'freelance', 'not_available')),
  english_level       text CHECK (english_level IS NULL OR english_level IN
                          ('basic', 'conversational', 'professional', 'fluent', 'native')),
  chinese_level       text CHECK (chinese_level IS NULL OR chinese_level IN
                          ('basic', 'conversational', 'professional', 'fluent', 'native')),
  open_to_relocation  boolean NOT NULL DEFAULT false,
  portfolio_url       text,
  resume_url          text,
  -- Verified by the trust & safety team (verification_documents in 013).
  is_verified         boolean NOT NULL DEFAULT false,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_worker_profiles_availability
  ON worker_profiles (availability);

CREATE OR REPLACE TRIGGER trg_worker_profiles_updated_at
  BEFORE UPDATE ON worker_profiles
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Worker <-> skill, with self-rated proficiency.
CREATE TABLE IF NOT EXISTS worker_skills (
  worker_profile_id uuid NOT NULL
                      REFERENCES worker_profiles (id) ON DELETE CASCADE,
  skill_id          uuid NOT NULL REFERENCES skills (id) ON DELETE CASCADE,
  proficiency       text NOT NULL DEFAULT 'intermediate'
                      CHECK (proficiency IN
                        ('beginner', 'intermediate', 'advanced', 'expert')),
  years             int CHECK (years IS NULL OR years >= 0),
  PRIMARY KEY (worker_profile_id, skill_id)
);

-- Reverse lookup: "who has skill X?".
CREATE INDEX IF NOT EXISTS idx_worker_skills_skill_id ON worker_skills (skill_id);


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/005_company_profiles.sql
-- =====================================================================
-- 005_company_profiles.sql
-- Employer organizations, plus the membership table that grants profiles
-- access to act on behalf of a company. company_members is the source of
-- truth for "can this user manage this company's listings / offers / billing".

CREATE TABLE IF NOT EXISTS company_profiles (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- The profile that created the company. Kept for provenance; day-to-day
  -- authorization goes through company_members.
  owner_profile_id      uuid NOT NULL REFERENCES profiles (id) ON DELETE RESTRICT,
  name                  text NOT NULL,
  slug                  text NOT NULL UNIQUE,
  website               text,
  description           text,
  industry              text,
  size                  text CHECK (size IS NULL OR size IN
                          ('1-10', '11-50', '51-200', '201-500', '501-1000', '1000+')),
  headquarters_country  text,                       -- ISO 3166-1 alpha-2
  logo_url              text,
  is_verified           boolean NOT NULL DEFAULT false,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_company_profiles_owner ON company_profiles (owner_profile_id);
CREATE INDEX IF NOT EXISTS idx_company_profiles_name_trgm
  ON company_profiles USING gin (name gin_trgm_ops);

CREATE OR REPLACE TRIGGER trg_company_profiles_updated_at
  BEFORE UPDATE ON company_profiles
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- A profile's seat at a company, with a role that scopes what they can do.
CREATE TABLE IF NOT EXISTS company_members (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id  uuid NOT NULL REFERENCES company_profiles (id) ON DELETE CASCADE,
  profile_id  uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  role        text NOT NULL DEFAULT 'member'
                CHECK (role IN ('owner', 'admin', 'recruiter', 'member')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  -- A profile holds at most one seat per company.
  UNIQUE (company_id, profile_id)
);

CREATE INDEX IF NOT EXISTS idx_company_members_profile ON company_members (profile_id);
CREATE INDEX IF NOT EXISTS idx_company_members_company ON company_members (company_id);


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/006_listings.sql
-- =====================================================================
-- 006_listings.sql
-- UNIFIED listings: a single table with a `type` discriminator
-- ('freelance' | 'fulltime'). Type-specific columns live in sibling 1:1
-- detail tables (freelance_details / fulltime_details) so the core table stays
-- lean and shared concerns (status, skills, saves) work uniformly across both.

CREATE TABLE IF NOT EXISTS listings (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id      uuid NOT NULL REFERENCES company_profiles (id) ON DELETE CASCADE,
  posted_by       uuid REFERENCES profiles (id) ON DELETE SET NULL,
  -- Discriminator. Drives which detail table applies.
  type            text NOT NULL CHECK (type IN ('freelance', 'fulltime')),
  title           text NOT NULL,
  description     text,
  category_id     uuid REFERENCES categories (id) ON DELETE SET NULL,
  status          text NOT NULL DEFAULT 'draft'
                    CHECK (status IN ('draft', 'open', 'paused', 'closed', 'filled')),
  location_type   text NOT NULL DEFAULT 'remote'
                    CHECK (location_type IN ('remote', 'hybrid', 'onsite')),
  location_country text,                            -- ISO 3166-1 alpha-2
  currency        text NOT NULL DEFAULT 'USD',
  published_at    timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

-- Public browse queries filter by status + type + category; partial index on
-- the hot path (only open listings are publicly searched).
CREATE INDEX IF NOT EXISTS idx_listings_open
  ON listings (type, category_id) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS idx_listings_company ON listings (company_id);
CREATE INDEX IF NOT EXISTS idx_listings_status ON listings (status);
CREATE INDEX IF NOT EXISTS idx_listings_title_trgm
  ON listings USING gin (title gin_trgm_ops);

CREATE OR REPLACE TRIGGER trg_listings_updated_at
  BEFORE UPDATE ON listings
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Freelance-specific terms (1:1 with a listing where type = 'freelance').
CREATE TABLE IF NOT EXISTS freelance_details (
  listing_id              uuid PRIMARY KEY
                            REFERENCES listings (id) ON DELETE CASCADE,
  budget_type             text NOT NULL DEFAULT 'fixed'
                            CHECK (budget_type IN ('fixed', 'hourly')),
  budget_min              numeric(12, 2) CHECK (budget_min IS NULL OR budget_min >= 0),
  budget_max              numeric(12, 2) CHECK (budget_max IS NULL OR budget_max >= 0),
  estimated_hours         int CHECK (estimated_hours IS NULL OR estimated_hours >= 0),
  estimated_duration_weeks int CHECK (estimated_duration_weeks IS NULL OR estimated_duration_weeks >= 0),
  deadline                date,
  CHECK (budget_max IS NULL OR budget_min IS NULL OR budget_max >= budget_min)
);

-- Full-time-specific terms (1:1 with a listing where type = 'fulltime').
CREATE TABLE IF NOT EXISTS fulltime_details (
  listing_id        uuid PRIMARY KEY
                      REFERENCES listings (id) ON DELETE CASCADE,
  employment_type   text NOT NULL DEFAULT 'full_time'
                      CHECK (employment_type IN ('full_time', 'part_time', 'contract')),
  salary_min        numeric(12, 2) CHECK (salary_min IS NULL OR salary_min >= 0),
  salary_max        numeric(12, 2) CHECK (salary_max IS NULL OR salary_max >= 0),
  salary_period     text NOT NULL DEFAULT 'year'
                      CHECK (salary_period IN ('year', 'month', 'hour')),
  seniority         text CHECK (seniority IS NULL OR seniority IN
                      ('intern', 'junior', 'mid', 'senior', 'lead', 'principal')),
  benefits          text,
  CHECK (salary_max IS NULL OR salary_min IS NULL OR salary_max >= salary_min)
);

-- Skills a listing asks for.
CREATE TABLE IF NOT EXISTS listing_skills (
  listing_id  uuid NOT NULL REFERENCES listings (id) ON DELETE CASCADE,
  skill_id    uuid NOT NULL REFERENCES skills (id) ON DELETE CASCADE,
  is_required boolean NOT NULL DEFAULT true,
  PRIMARY KEY (listing_id, skill_id)
);

CREATE INDEX IF NOT EXISTS idx_listing_skills_skill ON listing_skills (skill_id);

-- A worker's bookmarked listings.
CREATE TABLE IF NOT EXISTS saved_listings (
  profile_id  uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  listing_id  uuid NOT NULL REFERENCES listings (id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (profile_id, listing_id)
);


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/007_applications.sql
-- =====================================================================
-- 007_applications.sql
-- A worker's application to a listing. One application per (listing, worker).

CREATE TABLE IF NOT EXISTS applications (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id        uuid NOT NULL REFERENCES listings (id) ON DELETE CASCADE,
  worker_profile_id uuid NOT NULL
                      REFERENCES worker_profiles (id) ON DELETE CASCADE,
  cover_letter      text,
  -- What the worker proposes to be paid; interpretation depends on listing type
  -- (hourly/fixed for freelance, salary for full-time).
  proposed_rate     numeric(12, 2) CHECK (proposed_rate IS NULL OR proposed_rate >= 0),
  status            text NOT NULL DEFAULT 'submitted'
                      CHECK (status IN
                        ('submitted', 'reviewing', 'shortlisted', 'rejected',
                         'withdrawn', 'offered', 'hired')),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  -- A worker can apply to a given listing only once.
  UNIQUE (listing_id, worker_profile_id)
);

-- Employer view: applications for a listing, filtered by status.
CREATE INDEX IF NOT EXISTS idx_applications_listing_status
  ON applications (listing_id, status);
-- Worker view: "my applications".
CREATE INDEX IF NOT EXISTS idx_applications_worker
  ON applications (worker_profile_id);

CREATE OR REPLACE TRIGGER trg_applications_updated_at
  BEFORE UPDATE ON applications
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/008_offers.sql
-- =====================================================================
-- 008_offers.sql
-- A formal offer from a company to a worker. May originate from an application
-- (application_id set) or be a direct/sourced offer (application_id NULL).
-- An accepted offer is what spawns an engagement (009).

CREATE TABLE IF NOT EXISTS offers (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  application_id        uuid REFERENCES applications (id) ON DELETE SET NULL,
  listing_id            uuid REFERENCES listings (id) ON DELETE SET NULL,
  company_id            uuid NOT NULL REFERENCES company_profiles (id) ON DELETE CASCADE,
  worker_profile_id     uuid NOT NULL
                          REFERENCES worker_profiles (id) ON DELETE CASCADE,
  type                  text NOT NULL CHECK (type IN ('freelance', 'fulltime')),
  compensation_amount   numeric(12, 2) NOT NULL CHECK (compensation_amount >= 0),
  compensation_period   text NOT NULL DEFAULT 'year'
                          CHECK (compensation_period IN ('year', 'month', 'hour', 'fixed')),
  currency              text NOT NULL DEFAULT 'USD',
  start_date            date,
  status                text NOT NULL DEFAULT 'draft'
                          CHECK (status IN
                            ('draft', 'sent', 'accepted', 'declined',
                             'rescinded', 'expired')),
  expires_at            timestamptz,
  terms                 text,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_offers_worker ON offers (worker_profile_id);
CREATE INDEX IF NOT EXISTS idx_offers_company ON offers (company_id);
CREATE INDEX IF NOT EXISTS idx_offers_status ON offers (status);

CREATE OR REPLACE TRIGGER trg_offers_updated_at
  BEFORE UPDATE ON offers
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/009_engagements.sql
-- =====================================================================
-- 009_engagements.sql
-- THE REVENUE SPINE. An engagement is a live working relationship created when
-- an offer is accepted. Billing (011) and reviews/disputes (013) all reference
-- it.
--
-- WHY fee rates are columns here (and not looked up live): they are SNAPSHOTTED
-- at engagement creation. If the platform later changes its pricing, existing
-- engagements keep billing at the rate the parties agreed to. This is the
-- single most important data-integrity decision in the financial model.

CREATE TABLE IF NOT EXISTS engagements (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  offer_id              uuid REFERENCES offers (id) ON DELETE SET NULL,
  listing_id            uuid REFERENCES listings (id) ON DELETE SET NULL,
  company_id            uuid NOT NULL REFERENCES company_profiles (id) ON DELETE RESTRICT,
  worker_profile_id     uuid NOT NULL
                          REFERENCES worker_profiles (id) ON DELETE RESTRICT,
  type                  text NOT NULL CHECK (type IN ('freelance', 'fulltime')),
  status                text NOT NULL DEFAULT 'active'
                          CHECK (status IN ('active', 'paused', 'completed', 'terminated')),
  start_date            date NOT NULL DEFAULT CURRENT_DATE,
  end_date              date,
  compensation_amount   numeric(12, 2) NOT NULL CHECK (compensation_amount >= 0),
  compensation_period   text NOT NULL DEFAULT 'year'
                          CHECK (compensation_period IN ('year', 'month', 'hour', 'fixed')),
  currency              text NOT NULL DEFAULT 'USD',

  -- --- Snapshotted fee rates (fractions, e.g. 0.1000 = 10%) ---
  -- 10% commission on first-year salary (employment placement).
  placement_fee_rate    numeric(5, 4) NOT NULL DEFAULT 0.1000
                          CHECK (placement_fee_rate >= 0 AND placement_fee_rate <= 1),
  -- 5% recurring annual retention fee.
  recurring_fee_rate    numeric(5, 4) NOT NULL DEFAULT 0.0500
                          CHECK (recurring_fee_rate >= 0 AND recurring_fee_rate <= 1),
  -- 1-2% payroll processing fee.
  payroll_fee_rate      numeric(5, 4) NOT NULL DEFAULT 0.0200
                          CHECK (payroll_fee_rate >= 0 AND payroll_fee_rate <= 1),

  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CHECK (end_date IS NULL OR end_date >= start_date)
);

CREATE INDEX IF NOT EXISTS idx_engagements_company ON engagements (company_id);
CREATE INDEX IF NOT EXISTS idx_engagements_worker ON engagements (worker_profile_id);
CREATE INDEX IF NOT EXISTS idx_engagements_status ON engagements (status);

CREATE OR REPLACE TRIGGER trg_engagements_updated_at
  BEFORE UPDATE ON engagements
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/010_messaging.sql
-- =====================================================================
-- 010_messaging.sql
-- Conversations, their participants, messages, and cached translations.
-- Access control is strict: only participants may read a conversation's
-- messages (enforced via RLS in 015, using is_conversation_participant()).

CREATE TABLE IF NOT EXISTS conversations (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subject       text,
  -- Optional context the conversation is attached to.
  listing_id    uuid REFERENCES listings (id) ON DELETE SET NULL,
  engagement_id uuid REFERENCES engagements (id) ON DELETE SET NULL,
  created_by    uuid REFERENCES profiles (id) ON DELETE SET NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE TRIGGER trg_conversations_updated_at
  BEFORE UPDATE ON conversations
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Membership in a conversation. This table is the access-control gate.
CREATE TABLE IF NOT EXISTS conversation_participants (
  conversation_id uuid NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  profile_id      uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  -- Read receipts: everything created at/before this is "read".
  last_read_at    timestamptz,
  joined_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (conversation_id, profile_id)
);

CREATE INDEX IF NOT EXISTS idx_conversation_participants_profile
  ON conversation_participants (profile_id);

CREATE TABLE IF NOT EXISTS messages (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id   uuid NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  sender_id         uuid REFERENCES profiles (id) ON DELETE SET NULL,
  body              text NOT NULL,
  original_language text,                           -- BCP-47, e.g. 'zh', 'en'
  created_at        timestamptz NOT NULL DEFAULT now(),
  edited_at         timestamptz,
  -- Soft delete so a removed message can stay referenced by translations/audit.
  deleted_at        timestamptz
);

-- Primary access pattern: fetch a conversation's messages newest-first.
CREATE INDEX IF NOT EXISTS idx_messages_conversation_created
  ON messages (conversation_id, created_at DESC);

-- Cached machine translations of a message (Google Cloud Translate). One row
-- per target language; we never re-translate the same (message, language).
CREATE TABLE IF NOT EXISTS message_translations (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  message_id      uuid NOT NULL REFERENCES messages (id) ON DELETE CASCADE,
  target_language text NOT NULL,                    -- BCP-47
  translated_body text NOT NULL,
  provider        text NOT NULL DEFAULT 'google',
  created_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (message_id, target_language)
);


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/011_billing.sql
-- =====================================================================
-- 011_billing.sql
-- Money movement. invoices = amounts the platform charges a company;
-- payroll_runs = periodic worker pay (gross/fee/net); payments = concrete
-- transactions that settle either an invoice or a payroll run.
-- All highly sensitive: RLS (015) restricts to the company/worker involved.

CREATE TABLE IF NOT EXISTS invoices (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  engagement_id   uuid REFERENCES engagements (id) ON DELETE SET NULL,
  company_id      uuid NOT NULL REFERENCES company_profiles (id) ON DELETE RESTRICT,
  invoice_number  text NOT NULL UNIQUE,
  -- Which revenue stream this invoice represents.
  type            text NOT NULL
                    CHECK (type IN
                      ('placement_fee', 'recurring_fee', 'payroll_fee', 'subscription')),
  amount          numeric(12, 2) NOT NULL CHECK (amount >= 0),
  currency        text NOT NULL DEFAULT 'USD',
  status          text NOT NULL DEFAULT 'draft'
                    CHECK (status IN ('draft', 'sent', 'paid', 'void', 'overdue')),
  issued_at       timestamptz,
  due_at          timestamptz,
  paid_at         timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_invoices_company ON invoices (company_id);
CREATE INDEX IF NOT EXISTS idx_invoices_engagement ON invoices (engagement_id);
CREATE INDEX IF NOT EXISTS idx_invoices_status ON invoices (status);

CREATE OR REPLACE TRIGGER trg_invoices_updated_at
  BEFORE UPDATE ON invoices
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS payroll_runs (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  engagement_id     uuid NOT NULL REFERENCES engagements (id) ON DELETE RESTRICT,
  company_id        uuid NOT NULL REFERENCES company_profiles (id) ON DELETE RESTRICT,
  worker_profile_id uuid NOT NULL REFERENCES worker_profiles (id) ON DELETE RESTRICT,
  period_start      date NOT NULL,
  period_end        date NOT NULL,
  gross_amount      numeric(12, 2) NOT NULL CHECK (gross_amount >= 0),
  fee_amount        numeric(12, 2) NOT NULL DEFAULT 0 CHECK (fee_amount >= 0),
  net_amount        numeric(12, 2) NOT NULL CHECK (net_amount >= 0),
  currency          text NOT NULL DEFAULT 'USD',
  status            text NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending', 'processing', 'paid', 'failed')),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CHECK (period_end >= period_start)
);

CREATE INDEX IF NOT EXISTS idx_payroll_runs_engagement ON payroll_runs (engagement_id);
CREATE INDEX IF NOT EXISTS idx_payroll_runs_worker ON payroll_runs (worker_profile_id);
CREATE INDEX IF NOT EXISTS idx_payroll_runs_company ON payroll_runs (company_id);

CREATE OR REPLACE TRIGGER trg_payroll_runs_updated_at
  BEFORE UPDATE ON payroll_runs
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- A concrete transaction. Exactly one of invoice_id / payroll_run_id is the
-- thing being settled (a loose XOR, enforced by the CHECK below).
CREATE TABLE IF NOT EXISTS payments (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id          uuid REFERENCES invoices (id) ON DELETE SET NULL,
  payroll_run_id      uuid REFERENCES payroll_runs (id) ON DELETE SET NULL,
  payer_profile_id    uuid REFERENCES profiles (id) ON DELETE SET NULL,
  payee_profile_id    uuid REFERENCES profiles (id) ON DELETE SET NULL,
  amount              numeric(12, 2) NOT NULL CHECK (amount >= 0),
  currency            text NOT NULL DEFAULT 'USD',
  direction           text NOT NULL CHECK (direction IN ('inbound', 'outbound')),
  provider            text,                         -- e.g. 'stripe', 'wise'
  provider_reference  text,
  status              text NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'succeeded', 'failed', 'refunded')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  -- A payment settles an invoice or a payroll run, not both, not neither.
  CHECK ((invoice_id IS NOT NULL) <> (payroll_run_id IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS idx_payments_invoice ON payments (invoice_id);
CREATE INDEX IF NOT EXISTS idx_payments_payroll_run ON payments (payroll_run_id);
CREATE INDEX IF NOT EXISTS idx_payments_payer ON payments (payer_profile_id);
CREATE INDEX IF NOT EXISTS idx_payments_payee ON payments (payee_profile_id);

CREATE OR REPLACE TRIGGER trg_payments_updated_at
  BEFORE UPDATE ON payments
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/012_subscriptions.sql
-- =====================================================================
-- 012_subscriptions.sql
-- Premium plans for the "premium tools and services" revenue stream. A
-- subscription belongs to either an individual profile or a company (XOR).

CREATE TABLE IF NOT EXISTS subscriptions (
  id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subscriber_profile_id   uuid REFERENCES profiles (id) ON DELETE CASCADE,
  company_id              uuid REFERENCES company_profiles (id) ON DELETE CASCADE,
  plan                    text NOT NULL DEFAULT 'free'
                            CHECK (plan IN ('free', 'pro', 'enterprise')),
  status                  text NOT NULL DEFAULT 'active'
                            CHECK (status IN
                              ('active', 'trialing', 'past_due', 'canceled')),
  current_period_start    timestamptz,
  current_period_end      timestamptz,
  provider                text,                     -- e.g. 'stripe'
  provider_subscription_id text,
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  -- A subscription is owned by a person or a company, exactly one.
  CHECK ((subscriber_profile_id IS NOT NULL) <> (company_id IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS idx_subscriptions_profile ON subscriptions (subscriber_profile_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_company ON subscriptions (company_id);

CREATE OR REPLACE TRIGGER trg_subscriptions_updated_at
  BEFORE UPDATE ON subscriptions
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/013_trust_safety.sql
-- =====================================================================
-- 013_trust_safety.sql
-- Reviews between engaged parties, disputes, and KYC/verification documents.

-- A review is written by one party of an engagement about the other. One review
-- per (engagement, author).
CREATE TABLE IF NOT EXISTS reviews (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  engagement_id       uuid NOT NULL REFERENCES engagements (id) ON DELETE CASCADE,
  author_profile_id   uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  subject_profile_id  uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  rating              int NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment             text,
  is_public           boolean NOT NULL DEFAULT true,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (engagement_id, author_profile_id),
  CHECK (author_profile_id <> subject_profile_id)
);

CREATE INDEX IF NOT EXISTS idx_reviews_subject ON reviews (subject_profile_id);
CREATE INDEX IF NOT EXISTS idx_reviews_engagement ON reviews (engagement_id);

CREATE OR REPLACE TRIGGER trg_reviews_updated_at
  BEFORE UPDATE ON reviews
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- A formal dispute over an engagement or invoice.
CREATE TABLE IF NOT EXISTS disputes (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  engagement_id       uuid REFERENCES engagements (id) ON DELETE SET NULL,
  invoice_id          uuid REFERENCES invoices (id) ON DELETE SET NULL,
  raised_by           uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  against_profile_id  uuid REFERENCES profiles (id) ON DELETE SET NULL,
  reason              text NOT NULL,
  description         text,
  status              text NOT NULL DEFAULT 'open'
                        CHECK (status IN
                          ('open', 'under_review', 'resolved', 'rejected', 'withdrawn')),
  resolution          text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  resolved_at         timestamptz
);

CREATE INDEX IF NOT EXISTS idx_disputes_raised_by ON disputes (raised_by);
CREATE INDEX IF NOT EXISTS idx_disputes_status ON disputes (status);

CREATE OR REPLACE TRIGGER trg_disputes_updated_at
  BEFORE UPDATE ON disputes
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- KYC / verification documents. Highly sensitive PII: RLS (015) restricts reads
-- to the owning profile and admins only.
CREATE TABLE IF NOT EXISTS verification_documents (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id    uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  company_id    uuid REFERENCES company_profiles (id) ON DELETE CASCADE,
  doc_type      text NOT NULL
                  CHECK (doc_type IN
                    ('id', 'passport', 'business_license', 'address_proof', 'other')),
  file_url      text NOT NULL,
  status        text NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'approved', 'rejected')),
  reviewed_by   uuid REFERENCES profiles (id) ON DELETE SET NULL,
  review_notes  text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  reviewed_at   timestamptz
);

CREATE INDEX IF NOT EXISTS idx_verification_documents_profile
  ON verification_documents (profile_id);
CREATE INDEX IF NOT EXISTS idx_verification_documents_status
  ON verification_documents (status);

CREATE OR REPLACE TRIGGER trg_verification_documents_updated_at
  BEFORE UPDATE ON verification_documents
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/014_notifications_audit.sql
-- =====================================================================
-- 014_notifications_audit.sql
-- Per-user notifications and an append-only audit log.

CREATE TABLE IF NOT EXISTS notifications (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_profile_id  uuid NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  type                  text NOT NULL,              -- e.g. 'offer.received'
  title                 text NOT NULL,
  body                  text,
  data                  jsonb NOT NULL DEFAULT '{}'::jsonb,  -- structured payload
  is_read               boolean NOT NULL DEFAULT false,
  read_at               timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now()
);

-- Inbox query: a recipient's unread/recent notifications.
CREATE INDEX IF NOT EXISTS idx_notifications_recipient_unread
  ON notifications (recipient_profile_id, created_at DESC)
  WHERE is_read = false;

-- Append-only audit trail. WHY no updated_at / no trigger: audit rows are
-- immutable by design; RLS (015) forbids UPDATE/DELETE for non-service callers.
CREATE TABLE IF NOT EXISTS audit_logs (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_profile_id uuid REFERENCES profiles (id) ON DELETE SET NULL,
  action        text NOT NULL,                      -- e.g. 'offer.accepted'
  entity_type   text,                               -- e.g. 'offers'
  entity_id     uuid,
  metadata      jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip_address    inet,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_audit_logs_actor ON audit_logs (actor_profile_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_entity ON audit_logs (entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_created ON audit_logs (created_at DESC);


-- =====================================================================
-- SOURCE: apps/api/src/db/migrations/015_rls_policies.sql
-- =====================================================================
-- 015_rls_policies.sql
-- =====================================================================
-- ROW LEVEL SECURITY — the platform's #1 security control.
-- =====================================================================
-- Strategy (the Supabase model):
--   1. GRANT table privileges to the anon / authenticated roles so they can
--      reach the tables at all.
--   2. ENABLE (and FORCE) RLS on every table, so access is default-DENY.
--   3. Add precise per-operation policies that re-open only the rows a caller
--      is entitled to.
--
-- All authorization predicates live in SECURITY DEFINER helper functions.
-- WHY SECURITY DEFINER: a policy on company_members that itself queries
-- company_members would recurse infinitely under RLS. Running the check as the
-- table owner (which bypasses RLS) breaks that cycle. search_path is pinned to
-- prevent search-path hijacking of a definer-rights function.
--
-- Idempotent: every policy is DROP ... IF EXISTS then CREATE.

-- ---------------------------------------------------------------------------
-- Privilege grants (RLS still filters rows after these)
-- ---------------------------------------------------------------------------
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;

-- Authenticated users may attempt all DML; policies decide which rows succeed.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO authenticated;

-- Anonymous (logged-out) visitors may only read the publicly browsable surface.
GRANT SELECT ON
  categories, skills, company_profiles,
  listings, freelance_details, fulltime_details, listing_skills
TO anon;

-- service_role is the trusted backend; it also has BYPASSRLS from 001.
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;

-- Keep grants working for anything created later in the public schema.
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT ALL ON TABLES TO service_role;

-- ---------------------------------------------------------------------------
-- Authorization helper functions (SECURITY DEFINER, RLS-bypassing)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION is_admin()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = app_current_user_id() AND role = 'admin'
  );
$$;

-- True if the caller owns the given worker_profile.
CREATE OR REPLACE FUNCTION owns_worker_profile(p_worker_profile_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM worker_profiles
    WHERE id = p_worker_profile_id AND profile_id = app_current_user_id()
  );
$$;

-- True if the caller holds any seat at the company.
CREATE OR REPLACE FUNCTION is_company_member(p_company_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM company_members
    WHERE company_id = p_company_id AND profile_id = app_current_user_id()
  );
$$;

-- True if the caller is an owner/admin of the company (manage members, settings).
CREATE OR REPLACE FUNCTION is_company_admin(p_company_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM company_members
    WHERE company_id = p_company_id
      AND profile_id = app_current_user_id()
      AND role IN ('owner', 'admin')
  );
$$;

-- True if the caller is a participant in the conversation.
CREATE OR REPLACE FUNCTION is_conversation_participant(p_conversation_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM conversation_participants
    WHERE conversation_id = p_conversation_id
      AND profile_id = app_current_user_id()
  );
$$;

-- Visibility test for a listing: open to the world, or visible to its company.
CREATE OR REPLACE FUNCTION can_read_listing(p_listing_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM listings l
    WHERE l.id = p_listing_id
      AND (l.status = 'open' OR is_company_member(l.company_id))
  );
$$;

-- Management test for a listing: caller is a member of the owning company.
CREATE OR REPLACE FUNCTION can_manage_listing(p_listing_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM listings l
    WHERE l.id = p_listing_id AND is_company_member(l.company_id)
  );
$$;

GRANT EXECUTE ON FUNCTION
  app_current_user_id(), app_is_authenticated(), is_admin(),
  owns_worker_profile(uuid), is_company_member(uuid), is_company_admin(uuid),
  is_conversation_participant(uuid), can_read_listing(uuid), can_manage_listing(uuid)
TO anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Enable + FORCE RLS on every table.
-- FORCE so that even the table owner is subject to policies — defense in depth.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  t text;
  tables text[] := ARRAY[
    'profiles', 'categories', 'skills', 'worker_profiles', 'worker_skills',
    'company_profiles', 'company_members', 'listings', 'freelance_details',
    'fulltime_details', 'listing_skills', 'saved_listings', 'applications',
    'offers', 'engagements', 'conversations', 'conversation_participants',
    'messages', 'message_translations', 'invoices', 'payroll_runs', 'payments',
    'subscriptions', 'reviews', 'disputes', 'verification_documents',
    'notifications', 'audit_logs'
  ];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY;', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY;', t);
  END LOOP;
END
$$;

-- ===========================================================================
-- POLICIES
-- ===========================================================================

-- ----- profiles -----------------------------------------------------------
-- A user sees only their own profile (or admins see all). Public-facing display
-- data is surfaced through dedicated views, not by opening this table.
DROP POLICY IF EXISTS profiles_select_self ON profiles;
CREATE POLICY profiles_select_self ON profiles FOR SELECT TO authenticated
  USING (id = app_current_user_id() OR is_admin());

DROP POLICY IF EXISTS profiles_insert_self ON profiles;
CREATE POLICY profiles_insert_self ON profiles FOR INSERT TO authenticated
  WITH CHECK (id = app_current_user_id());

DROP POLICY IF EXISTS profiles_update_self ON profiles;
CREATE POLICY profiles_update_self ON profiles FOR UPDATE TO authenticated
  USING (id = app_current_user_id() OR is_admin())
  WITH CHECK (id = app_current_user_id() OR is_admin());

-- ----- categories / skills (public read, admin write) ---------------------
DROP POLICY IF EXISTS categories_select_all ON categories;
CREATE POLICY categories_select_all ON categories FOR SELECT TO anon, authenticated
  USING (true);
DROP POLICY IF EXISTS categories_write_admin ON categories;
CREATE POLICY categories_write_admin ON categories FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

DROP POLICY IF EXISTS skills_select_all ON skills;
CREATE POLICY skills_select_all ON skills FOR SELECT TO anon, authenticated
  USING (true);
DROP POLICY IF EXISTS skills_write_admin ON skills;
CREATE POLICY skills_write_admin ON skills FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

-- ----- worker_profiles (talent directory: readable by signed-in users) ----
DROP POLICY IF EXISTS worker_profiles_select ON worker_profiles;
CREATE POLICY worker_profiles_select ON worker_profiles FOR SELECT TO authenticated
  USING (true);
DROP POLICY IF EXISTS worker_profiles_insert_self ON worker_profiles;
CREATE POLICY worker_profiles_insert_self ON worker_profiles FOR INSERT TO authenticated
  WITH CHECK (profile_id = app_current_user_id());
DROP POLICY IF EXISTS worker_profiles_update_self ON worker_profiles;
CREATE POLICY worker_profiles_update_self ON worker_profiles FOR UPDATE TO authenticated
  USING (profile_id = app_current_user_id() OR is_admin())
  WITH CHECK (profile_id = app_current_user_id() OR is_admin());
DROP POLICY IF EXISTS worker_profiles_delete_self ON worker_profiles;
CREATE POLICY worker_profiles_delete_self ON worker_profiles FOR DELETE TO authenticated
  USING (profile_id = app_current_user_id() OR is_admin());

-- ----- worker_skills ------------------------------------------------------
DROP POLICY IF EXISTS worker_skills_select ON worker_skills;
CREATE POLICY worker_skills_select ON worker_skills FOR SELECT TO authenticated
  USING (true);
DROP POLICY IF EXISTS worker_skills_write_owner ON worker_skills;
CREATE POLICY worker_skills_write_owner ON worker_skills FOR ALL TO authenticated
  USING (owns_worker_profile(worker_profile_id))
  WITH CHECK (owns_worker_profile(worker_profile_id));

-- ----- company_profiles ---------------------------------------------------
DROP POLICY IF EXISTS company_profiles_select_all ON company_profiles;
CREATE POLICY company_profiles_select_all ON company_profiles FOR SELECT TO anon, authenticated
  USING (true);
DROP POLICY IF EXISTS company_profiles_insert_self ON company_profiles;
CREATE POLICY company_profiles_insert_self ON company_profiles FOR INSERT TO authenticated
  WITH CHECK (owner_profile_id = app_current_user_id());
DROP POLICY IF EXISTS company_profiles_update_admin ON company_profiles;
CREATE POLICY company_profiles_update_admin ON company_profiles FOR UPDATE TO authenticated
  USING (is_company_admin(id) OR is_admin())
  WITH CHECK (is_company_admin(id) OR is_admin());

-- ----- company_members ----------------------------------------------------
DROP POLICY IF EXISTS company_members_select ON company_members;
CREATE POLICY company_members_select ON company_members FOR SELECT TO authenticated
  USING (profile_id = app_current_user_id() OR is_company_member(company_id) OR is_admin());
DROP POLICY IF EXISTS company_members_write_admin ON company_members;
CREATE POLICY company_members_write_admin ON company_members FOR ALL TO authenticated
  USING (is_company_admin(company_id) OR is_admin())
  WITH CHECK (is_company_admin(company_id) OR is_admin());

-- ----- listings -----------------------------------------------------------
-- Anyone (including logged-out) can read OPEN listings. Company members also
-- see their own drafts/paused/closed. Only members can write.
DROP POLICY IF EXISTS listings_select ON listings;
CREATE POLICY listings_select ON listings FOR SELECT TO anon, authenticated
  USING (status = 'open' OR is_company_member(company_id));
DROP POLICY IF EXISTS listings_insert_member ON listings;
CREATE POLICY listings_insert_member ON listings FOR INSERT TO authenticated
  WITH CHECK (is_company_member(company_id));
DROP POLICY IF EXISTS listings_update_member ON listings;
CREATE POLICY listings_update_member ON listings FOR UPDATE TO authenticated
  USING (is_company_member(company_id))
  WITH CHECK (is_company_member(company_id));
DROP POLICY IF EXISTS listings_delete_member ON listings;
CREATE POLICY listings_delete_member ON listings FOR DELETE TO authenticated
  USING (is_company_member(company_id));

-- ----- freelance_details / fulltime_details (follow listing visibility) ---
DROP POLICY IF EXISTS freelance_details_select ON freelance_details;
CREATE POLICY freelance_details_select ON freelance_details FOR SELECT TO anon, authenticated
  USING (can_read_listing(listing_id));
DROP POLICY IF EXISTS freelance_details_write ON freelance_details;
CREATE POLICY freelance_details_write ON freelance_details FOR ALL TO authenticated
  USING (can_manage_listing(listing_id)) WITH CHECK (can_manage_listing(listing_id));

DROP POLICY IF EXISTS fulltime_details_select ON fulltime_details;
CREATE POLICY fulltime_details_select ON fulltime_details FOR SELECT TO anon, authenticated
  USING (can_read_listing(listing_id));
DROP POLICY IF EXISTS fulltime_details_write ON fulltime_details;
CREATE POLICY fulltime_details_write ON fulltime_details FOR ALL TO authenticated
  USING (can_manage_listing(listing_id)) WITH CHECK (can_manage_listing(listing_id));

-- ----- listing_skills -----------------------------------------------------
DROP POLICY IF EXISTS listing_skills_select ON listing_skills;
CREATE POLICY listing_skills_select ON listing_skills FOR SELECT TO anon, authenticated
  USING (can_read_listing(listing_id));
DROP POLICY IF EXISTS listing_skills_write ON listing_skills;
CREATE POLICY listing_skills_write ON listing_skills FOR ALL TO authenticated
  USING (can_manage_listing(listing_id)) WITH CHECK (can_manage_listing(listing_id));

-- ----- saved_listings (private to the saver) ------------------------------
DROP POLICY IF EXISTS saved_listings_own ON saved_listings;
CREATE POLICY saved_listings_own ON saved_listings FOR ALL TO authenticated
  USING (profile_id = app_current_user_id())
  WITH CHECK (profile_id = app_current_user_id());

-- ----- applications -------------------------------------------------------
-- Visible to the applying worker and to the hiring company. Workers create and
-- may update (withdraw) their own; companies may update status.
DROP POLICY IF EXISTS applications_select ON applications;
CREATE POLICY applications_select ON applications FOR SELECT TO authenticated
  USING (owns_worker_profile(worker_profile_id) OR can_manage_listing(listing_id) OR is_admin());
DROP POLICY IF EXISTS applications_insert_worker ON applications;
CREATE POLICY applications_insert_worker ON applications FOR INSERT TO authenticated
  WITH CHECK (owns_worker_profile(worker_profile_id));
DROP POLICY IF EXISTS applications_update ON applications;
CREATE POLICY applications_update ON applications FOR UPDATE TO authenticated
  USING (owns_worker_profile(worker_profile_id) OR can_manage_listing(listing_id))
  WITH CHECK (owns_worker_profile(worker_profile_id) OR can_manage_listing(listing_id));

-- ----- offers -------------------------------------------------------------
-- Company creates/edits; worker can read and update status (accept/decline).
DROP POLICY IF EXISTS offers_select ON offers;
CREATE POLICY offers_select ON offers FOR SELECT TO authenticated
  USING (owns_worker_profile(worker_profile_id) OR is_company_member(company_id) OR is_admin());
DROP POLICY IF EXISTS offers_insert_company ON offers;
CREATE POLICY offers_insert_company ON offers FOR INSERT TO authenticated
  WITH CHECK (is_company_member(company_id));
DROP POLICY IF EXISTS offers_update ON offers;
CREATE POLICY offers_update ON offers FOR UPDATE TO authenticated
  USING (is_company_member(company_id) OR owns_worker_profile(worker_profile_id))
  WITH CHECK (is_company_member(company_id) OR owns_worker_profile(worker_profile_id));

-- ----- engagements (revenue spine) ----------------------------------------
DROP POLICY IF EXISTS engagements_select ON engagements;
CREATE POLICY engagements_select ON engagements FOR SELECT TO authenticated
  USING (owns_worker_profile(worker_profile_id) OR is_company_member(company_id) OR is_admin());
DROP POLICY IF EXISTS engagements_insert_company ON engagements;
CREATE POLICY engagements_insert_company ON engagements FOR INSERT TO authenticated
  WITH CHECK (is_company_member(company_id));
DROP POLICY IF EXISTS engagements_update_company ON engagements;
CREATE POLICY engagements_update_company ON engagements FOR UPDATE TO authenticated
  USING (is_company_member(company_id) OR is_admin())
  WITH CHECK (is_company_member(company_id) OR is_admin());

-- ----- conversations / participants / messages ----------------------------
DROP POLICY IF EXISTS conversations_select ON conversations;
CREATE POLICY conversations_select ON conversations FOR SELECT TO authenticated
  USING (is_conversation_participant(id) OR is_admin());
DROP POLICY IF EXISTS conversations_insert ON conversations;
CREATE POLICY conversations_insert ON conversations FOR INSERT TO authenticated
  WITH CHECK (created_by = app_current_user_id());
DROP POLICY IF EXISTS conversations_update ON conversations;
CREATE POLICY conversations_update ON conversations FOR UPDATE TO authenticated
  USING (is_conversation_participant(id))
  WITH CHECK (is_conversation_participant(id));

DROP POLICY IF EXISTS conv_participants_select ON conversation_participants;
CREATE POLICY conv_participants_select ON conversation_participants FOR SELECT TO authenticated
  USING (is_conversation_participant(conversation_id) OR is_admin());
-- Allow joining yourself, or an existing participant adding others.
DROP POLICY IF EXISTS conv_participants_insert ON conversation_participants;
CREATE POLICY conv_participants_insert ON conversation_participants FOR INSERT TO authenticated
  WITH CHECK (profile_id = app_current_user_id() OR is_conversation_participant(conversation_id));
DROP POLICY IF EXISTS conv_participants_delete ON conversation_participants;
CREATE POLICY conv_participants_delete ON conversation_participants FOR DELETE TO authenticated
  USING (profile_id = app_current_user_id() OR is_conversation_participant(conversation_id));

DROP POLICY IF EXISTS messages_select ON messages;
CREATE POLICY messages_select ON messages FOR SELECT TO authenticated
  USING (is_conversation_participant(conversation_id) OR is_admin());
DROP POLICY IF EXISTS messages_insert ON messages;
CREATE POLICY messages_insert ON messages FOR INSERT TO authenticated
  WITH CHECK (sender_id = app_current_user_id() AND is_conversation_participant(conversation_id));
DROP POLICY IF EXISTS messages_update_sender ON messages;
CREATE POLICY messages_update_sender ON messages FOR UPDATE TO authenticated
  USING (sender_id = app_current_user_id())
  WITH CHECK (sender_id = app_current_user_id());

DROP POLICY IF EXISTS message_translations_select ON message_translations;
CREATE POLICY message_translations_select ON message_translations FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM messages m
    WHERE m.id = message_translations.message_id
      AND is_conversation_participant(m.conversation_id)
  ));
DROP POLICY IF EXISTS message_translations_insert ON message_translations;
CREATE POLICY message_translations_insert ON message_translations FOR INSERT TO authenticated
  WITH CHECK (EXISTS (
    SELECT 1 FROM messages m
    WHERE m.id = message_translations.message_id
      AND is_conversation_participant(m.conversation_id)
  ));

-- ----- invoices / payroll_runs / payments (financial: parties only) --------
-- Reads only; writes are service_role/admin (no authenticated write policy).
DROP POLICY IF EXISTS invoices_select ON invoices;
CREATE POLICY invoices_select ON invoices FOR SELECT TO authenticated
  USING (is_company_member(company_id) OR is_admin());
DROP POLICY IF EXISTS invoices_write_admin ON invoices;
CREATE POLICY invoices_write_admin ON invoices FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

DROP POLICY IF EXISTS payroll_runs_select ON payroll_runs;
CREATE POLICY payroll_runs_select ON payroll_runs FOR SELECT TO authenticated
  USING (owns_worker_profile(worker_profile_id) OR is_company_member(company_id) OR is_admin());
DROP POLICY IF EXISTS payroll_runs_write_admin ON payroll_runs;
CREATE POLICY payroll_runs_write_admin ON payroll_runs FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

DROP POLICY IF EXISTS payments_select ON payments;
CREATE POLICY payments_select ON payments FOR SELECT TO authenticated
  USING (
    payer_profile_id = app_current_user_id()
    OR payee_profile_id = app_current_user_id()
    OR is_admin()
    OR EXISTS (SELECT 1 FROM invoices i
               WHERE i.id = payments.invoice_id AND is_company_member(i.company_id))
    OR EXISTS (SELECT 1 FROM payroll_runs pr
               WHERE pr.id = payments.payroll_run_id
                 AND (owns_worker_profile(pr.worker_profile_id) OR is_company_member(pr.company_id)))
  );
DROP POLICY IF EXISTS payments_write_admin ON payments;
CREATE POLICY payments_write_admin ON payments FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

-- ----- subscriptions ------------------------------------------------------
DROP POLICY IF EXISTS subscriptions_select ON subscriptions;
CREATE POLICY subscriptions_select ON subscriptions FOR SELECT TO authenticated
  USING (
    subscriber_profile_id = app_current_user_id()
    OR (company_id IS NOT NULL AND is_company_member(company_id))
    OR is_admin()
  );
DROP POLICY IF EXISTS subscriptions_write ON subscriptions;
CREATE POLICY subscriptions_write ON subscriptions FOR ALL TO authenticated
  USING (
    subscriber_profile_id = app_current_user_id()
    OR (company_id IS NOT NULL AND is_company_admin(company_id))
    OR is_admin()
  )
  WITH CHECK (
    subscriber_profile_id = app_current_user_id()
    OR (company_id IS NOT NULL AND is_company_admin(company_id))
    OR is_admin()
  );

-- ----- reviews ------------------------------------------------------------
DROP POLICY IF EXISTS reviews_select ON reviews;
CREATE POLICY reviews_select ON reviews FOR SELECT TO authenticated
  USING (is_public OR author_profile_id = app_current_user_id()
         OR subject_profile_id = app_current_user_id() OR is_admin());
DROP POLICY IF EXISTS reviews_insert_author ON reviews;
CREATE POLICY reviews_insert_author ON reviews FOR INSERT TO authenticated
  WITH CHECK (author_profile_id = app_current_user_id());
DROP POLICY IF EXISTS reviews_update_author ON reviews;
CREATE POLICY reviews_update_author ON reviews FOR UPDATE TO authenticated
  USING (author_profile_id = app_current_user_id())
  WITH CHECK (author_profile_id = app_current_user_id());

-- ----- disputes -----------------------------------------------------------
DROP POLICY IF EXISTS disputes_select ON disputes;
CREATE POLICY disputes_select ON disputes FOR SELECT TO authenticated
  USING (raised_by = app_current_user_id()
         OR against_profile_id = app_current_user_id() OR is_admin());
DROP POLICY IF EXISTS disputes_insert ON disputes;
CREATE POLICY disputes_insert ON disputes FOR INSERT TO authenticated
  WITH CHECK (raised_by = app_current_user_id());
DROP POLICY IF EXISTS disputes_update ON disputes;
CREATE POLICY disputes_update ON disputes FOR UPDATE TO authenticated
  USING (raised_by = app_current_user_id() OR is_admin())
  WITH CHECK (raised_by = app_current_user_id() OR is_admin());

-- ----- verification_documents (sensitive PII: owner + admin only) ----------
DROP POLICY IF EXISTS verification_documents_select ON verification_documents;
CREATE POLICY verification_documents_select ON verification_documents FOR SELECT TO authenticated
  USING (profile_id = app_current_user_id() OR is_admin());
DROP POLICY IF EXISTS verification_documents_insert ON verification_documents;
CREATE POLICY verification_documents_insert ON verification_documents FOR INSERT TO authenticated
  WITH CHECK (profile_id = app_current_user_id());
-- Only admins/reviewers change status; owner cannot self-approve.
DROP POLICY IF EXISTS verification_documents_update_admin ON verification_documents;
CREATE POLICY verification_documents_update_admin ON verification_documents FOR UPDATE TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

-- ----- notifications (private to recipient) -------------------------------
DROP POLICY IF EXISTS notifications_select_own ON notifications;
CREATE POLICY notifications_select_own ON notifications FOR SELECT TO authenticated
  USING (recipient_profile_id = app_current_user_id());
DROP POLICY IF EXISTS notifications_update_own ON notifications;
CREATE POLICY notifications_update_own ON notifications FOR UPDATE TO authenticated
  USING (recipient_profile_id = app_current_user_id())
  WITH CHECK (recipient_profile_id = app_current_user_id());
DROP POLICY IF EXISTS notifications_delete_own ON notifications;
CREATE POLICY notifications_delete_own ON notifications FOR DELETE TO authenticated
  USING (recipient_profile_id = app_current_user_id());
-- INSERT intentionally has no authenticated policy: notifications are emitted
-- by the backend (service_role), never by clients.

-- ----- audit_logs (admin read; writes are service_role only) --------------
DROP POLICY IF EXISTS audit_logs_select_admin ON audit_logs;
CREATE POLICY audit_logs_select_admin ON audit_logs FOR SELECT TO authenticated
  USING (is_admin());
-- No INSERT/UPDATE/DELETE policy for authenticated: the log is append-only and
-- written exclusively by the trusted backend.

